input.command:
cat > /tmp/lz4exp/compress-basic/runi.sh <<'EOF'
#!/bin/bash
# usage: runi.sh <label> <stdin-mode: null|yes|no|garbage|closed|txt> <args...>
D=/tmp/lz4exp/compress-basic
L="$1"; M="$2"; shift 2
echo "=== $L  [stdin=$M]"
printf '$ lz4'; printf ' %q' "$@"; printf '\n'
case "$M" in
  null) "/workspace/executable" "$@" </dev/null >$D/.o 2>$D/.e ;;
  yes)  printf 'y\n' | "/workspace/executable" "$@" >$D/.o 2>$D/.e ;;
  Y)    printf 'Y\n' | "/workspace/executable" "$@" >$D/.o 2>$D/.e ;;
  no)   printf 'n\n' | "/workspace/executable" "$@" >$D/.o 2>$D/.e ;;
  blank) printf '\n' | "/workspace/executable" "$@" >$D/.o 2>$D/.e ;;
  garbage) printf 'zzz\n' | "/workspace/executable" "$@" >$D/.o 2>$D/.e ;;
  closed) "/workspace/executable" "$@" <&- >$D/.o 2>$D/.e ;;
  *) "/workspace/executable" "$@" >$D/.o 2>$D/.e ;;
esac
rc=$?
echo "exit=$rc"
echo -n "stdout: "; python3 $D/dump.py $D/.o
echo -n "stderr: "; python3 $D/dump.py $D/.e
echo
EOF
chmod +x /tmp/lz4exp/compress-basic/runi.sh; echo ok
